const fs = require("node:fs");
const path = require("node:path");

/**
 * Bakes GOOGLE_DESKTOP_OAUTH_CLIENT_SECRET into a generated source file so it ships inside the packaged app
 * (electron-builder's `files` config only includes src/**, not loose repo-root files) - see
 * apps/desktop/.env.example for where this value comes from. Never edit or commit the generated file; it's
 * gitignored on purpose (see apps/desktop/src/oauth.js for how it's consumed, with a safe empty-string fallback
 * when this hasn't been run yet, e.g. a fresh `npm run dev`).
 */

const outPath = path.join(__dirname, "..", "src", "oauth-secret.generated.js");

function readLocalEnvFile() {
  const envPath = path.join(__dirname, "..", ".env");
  if (!fs.existsSync(envPath)) return {};

  const values = {};
  for (const line of fs.readFileSync(envPath, "utf8").split(/\r?\n/)) {
    const match = /^\s*([\w.-]+)\s*=\s*(.*)\s*$/.exec(line);
    if (match) {
      values[match[1]] = match[2].replace(/^["']|["']$/g, "");
    }
  }
  return values;
}

const secret = process.env.GOOGLE_DESKTOP_OAUTH_CLIENT_SECRET || readLocalEnvFile().GOOGLE_DESKTOP_OAUTH_CLIENT_SECRET || "";

fs.writeFileSync(
  outPath,
  `// Auto-generated by scripts/prepare-oauth-secret.js - do not edit or commit (see apps/desktop/.env.example).\n` +
    `module.exports = { GOOGLE_DESKTOP_OAUTH_CLIENT_SECRET: ${JSON.stringify(secret)} };\n`
);

console.log(
  secret
    ? "Google desktop OAuth secret bundled."
    : "No GOOGLE_DESKTOP_OAUTH_CLIENT_SECRET set (checked env var and apps/desktop/.env) - desktop Google sign-in will be disabled in this build."
);
